"""Write catalog/manifest/motion_utilities.json. Usage: python3 -I util_write_manifest.py <library_root>"""
import json, os, sys, subprocess
root = sys.argv[1]
def size(p):
    if not p: return None
    return subprocess.run(["du", "-sh", os.path.join(root, p)], capture_output=True, text=True).stdout.split()[0]
