out = []
for url, st, path, lic, items, notes, usage in E:
    out.append({"url": url, "status": st, "local_path": path, "license": lic,
                "size": size(path) if path else None, "items": items, "notes": notes, "usage": usage})
sites = {s[0] for g in json.load(open(os.path.join(root, "catalog/sites.json"))) for s in g["sites"]}
missing = [e["url"] for e in out if e["url"] not in sites]
assert not missing, missing
json.dump(out, open(os.path.join(root, "catalog/manifest/motion_utilities.json"), "w"), ensure_ascii=False, indent=2)
print(len(out), "entries")
